func sensitive_information(url,body,rsp,req) {
    for ruleName, rule = range payload {
        keys = re.FindAll(body, rule)
        keys = str.RemoveRepeat(keys)
        for _, key = range keys {
            shortKey = key
            if len(shortKey) > 20 {
                shortKey = key[:20]+"..."
            }
            risk.NewRisk(
                url, 
                risk.title("%s 疑似[%v]敏感信息: %v" % [ruleName, url, shortKey]), 
                risk.severity("info"), 
                risk.description(sprintf(
                    "%s 存在疑似敏感信息: RuleName %s: %s", 
                    url, 
                    ruleName, 
                    key, 
                )), 
                risk.solution(''), 
                risk.request(string(req)), 
                risk.response(string(rsp)), 
            )
        }
        if(keys!=nil){
            return true
        }else{
            return false
        }
    }
 
}

# 镜像全流量：所有经过MITM的流量都会被复制一份
mirrorHTTPFlow = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    // 正常请求和不正常请求对比响应包长度，去掉Cookie的请求和正常请求做对比

    nomal_req=req

    poc_req=poc.DeleteHTTPPacketHeader(req, "Cookie" /*type: string*/)
    poc_req=poc.DeleteHTTPPacketHeader(poc_req, "Token" /*type: string*/)

    nomal_req_headers=poc.GetHTTPPacketHeaders(nomal_req)
    poc_req_headers=poc.GetHTTPPacketHeaders(poc_req)
    
    req_body=poc.GetHTTPPacketBody(req)

    method=poc.GetHTTPRequestMethod(req)

    poc_resp,_,err:=poc.Do(method /*type: string*/, url /*type: string*/,poc.deleteHeader("Host"), poc.appendHeaders(poc_req_headers /*type: map[string]string*/),poc.body(req_body))
    if(err!=nil){
        yakit.Info(string(err));
    }

    nomal_resp,_,err:=poc.Do(method /*type: string*/, url /*type: string*/,poc.deleteHeader("Host"), poc.appendHeaders(nomal_req_headers /*type: map[string]string*/),poc.body(req_body))
    if(err!=nil){
        yakit.Info(string(err));
    }
    
    poc_resp_len=len(nomal_resp.GetBody())
    nomal_resp_len=len(poc_resp.GetBody())

    if(poc_resp_len==nomal_resp_len){
        if(sensitive_information(url, body, poc_req, poc_resp)){
            risk.NewRisk(url,
                risk.title("未授权访问敏感信息漏洞"),
                risk.request(poc_resp.RawRequest),
                risk.response(poc_resp.RawPacket),
                risk.description("可能存在未授权访问敏感信息漏洞"),
                risk.solution("添加Cookie校验")
            )
        }else{
            risk.NewRisk(url,
                risk.title("未授权访问漏洞"),
                risk.request(poc_resp.RawRequest),
                risk.response(poc_resp.RawPacket),
                risk.description("可能存在未授权访问漏洞"),
                risk.solution("添加Cookie校验")
            )
        }
 
    }
}
